namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone.",
                    "Stretch dough into a 12-inch round.",
                    "Spread crushed tomatoes over the dough.",
                    "Tear mozzarella and distribute evenly.",
                    "Bake for 10-12 minutes until crust is golden.",
                    "Top with fresh basil and a drizzle of olive oil."
                ],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted water until al dente.",
                    "Fry pancetta until crispy.",
                    "Whisk eggs with grated pecorino and pepper.",
                    "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.",
                    "Serve immediately with extra cheese and pepper."
                ],
                TotalRatings = 8, RatingSum = 36
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until charred.",
                    "Sauté onion, garlic, and ginger. Add tomato sauce and spices.",
                    "Simmer sauce for 15 minutes, then add cream.",
                    "Add chicken pieces and cook for 5 more minutes.",
                    "Serve with basmati rice or naan."
                ],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "Sweet, sour, and savory Thai noodles loaded with vegetables.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Eggs"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes.",
                    "Make sauce: mix tamarind paste, fish sauce, sugar, and lime juice.",
                    "Stir-fry tofu until golden, set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss with bean sprouts and tofu.",
                    "Serve with crushed peanuts and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef and drain excess fat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm tortillas in a dry skillet.",
                    "Fill tortillas with beef and desired toppings.",
                    "Serve with salsa and sour cream on the side."
                ],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit avocados, scoop into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, jalapeño, tomato, and cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 7, Title = "Japanese Miso Soup", Category = "Asian",
                Description = "Light and comforting soup with tofu and seaweed.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Green onion"],
                Steps = [
                    "Bring dashi stock to a gentle simmer.",
                    "Dissolve miso paste in a small amount of broth, then add to pot.",
                    "Add cubed tofu and rehydrated wakame.",
                    "Heat through without boiling (boiling destroys miso flavor).",
                    "Serve garnished with sliced green onion."
                ],
                TotalRatings = 5, RatingSum = 22
            },
            new Recipe
            {
                Id = 8, Title = "Palak Paneer", Category = "Indian",
                Description = "Creamy spinach curry with cubes of fresh paneer cheese.",
                Ingredients = ["Spinach", "Paneer", "Onion", "Garlic", "Ginger", "Green chili", "Cream", "Cumin seeds"],
                Steps = [
                    "Blanch spinach and blend into a smooth puree.",
                    "Fry paneer cubes until golden, set aside.",
                    "Sauté cumin seeds, onion, garlic, ginger, and green chili.",
                    "Add spinach puree and cook for 5 minutes.",
                    "Add paneer and cream, simmer for 3 minutes.",
                    "Serve with roti or rice."
                ],
                TotalRatings = 7, RatingSum = 31
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@page "/category/{CategoryName}"
@using RecipeShare.Services

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="text-warning mb-2">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <small class="text-muted ms-1">(@recipe.TotalRatings ratings)</small>
                        </div>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">&larr; Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeShare.Models.Recipe> _recipes = [];

    protected override void OnInitialized()
    {
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-link">&larr; Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <StarRating RecipeId="@_recipe.Id" />

    <div class="row mt-4">
        <div class="col-md-4">
            <h3>Ingredients</h3>
            <ul class="list-group">
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>

        <div class="col-md-8">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered">
                @foreach (var step in _recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added.</p>
        <a href="recipe/@_submittedId" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="needs-validation">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_title" class="form-control" placeholder="e.g., Grandma's Apple Pie" required />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_category" class="form-select" required>
                <option value="">— Select a category —</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Short Description</label>
            <InputTextArea id="description" @bind-Value="_description" class="form-control" rows="2"
                placeholder="A brief description of your recipe" required />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients</label>
            @for (int i = 0; i < _ingredients.Count; i++)
            {
                var index = i;
                <div class="input-group mb-2">
                    <input type="text" class="form-control" value="@_ingredients[index]"
                        placeholder="e.g., 2 cups flour"
                        @onchange="(e) => _ingredients[index] = e.Value?.ToString() ?? string.Empty" />
                    @if (_ingredients.Count > 1)
                    {
                        <button type="button" class="btn btn-outline-danger" @onclick="() => RemoveIngredient(index)">✕</button>
                    }
                </div>
            }
            <button type="button" class="btn btn-outline-secondary btn-sm" @onclick="AddIngredient">+ Add Ingredient</button>
        </div>

        <div class="mb-3">
            <label class="form-label">Steps</label>
            @for (int i = 0; i < _steps.Count; i++)
            {
                var index = i;
                <div class="input-group mb-2">
                    <span class="input-group-text">@(index + 1)</span>
                    <input type="text" class="form-control" value="@_steps[index]"
                        placeholder="Describe this step..."
                        @onchange="(e) => _steps[index] = e.Value?.ToString() ?? string.Empty" />
                    @if (_steps.Count > 1)
                    {
                        <button type="button" class="btn btn-outline-danger" @onclick="() => RemoveStep(index)">✕</button>
                    }
                </div>
            }
            <button type="button" class="btn btn-outline-secondary btn-sm" @onclick="AddStep">+ Add Step</button>
        </div>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="alert alert-danger">@_error</div>
        }

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _description = string.Empty;
    private List<string> _ingredients = [string.Empty];
    private List<string> _steps = [string.Empty];
    private string _error = string.Empty;
    private bool _submitted;
    private int _submittedId;
    private IReadOnlyList<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void AddIngredient() => _ingredients.Add(string.Empty);
    private void RemoveIngredient(int index) => _ingredients.RemoveAt(index);
    private void AddStep() => _steps.Add(string.Empty);
    private void RemoveStep(int index) => _steps.RemoveAt(index);

    private void HandleSubmit()
    {
        var ingredients = _ingredients.Where(i => !string.IsNullOrWhiteSpace(i)).ToList();
        var steps = _steps.Where(s => !string.IsNullOrWhiteSpace(s)).ToList();

        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category)
            || ingredients.Count == 0 || steps.Count == 0)
        {
            _error = "Please fill in all fields with at least one ingredient and one step.";
            return;
        }

        var recipe = RecipeService.AddRecipe(_title, _category, _description, ingredients, steps);
        _submittedId = recipe.Id;
        _submitted = true;
        _error = string.Empty;
    }

    private void ResetForm()
    {
        _title = string.Empty;
        _category = string.Empty;
        _description = string.Empty;
        _ingredients = [string.Empty];
        _steps = [string.Empty];
        _submitted = false;
        _error = string.Empty;
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating my-3">
    @if (_hasRated)
    {
        <div class="alert alert-info py-2 px-3 d-inline-block">
            You rated this recipe @_userRating star@(_userRating == 1 ? "" : "s"). Thanks!
        </div>
        <br />
    }

    <span class="stars" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                class="btn-star @(star <= (_hovering > 0 ? _hovering : (int)Math.Round(_average)) ? "active" : "")"
                @onclick="() => Rate(star)"
                @onmouseover="() => _hovering = star"
                @onmouseout="() => _hovering = 0"
                disabled="@_hasRated"
                aria-label="Rate @star star@(star == 1 ? "" : "s")">
                @(star <= (_hovering > 0 ? _hovering : (int)Math.Round(_average)) ? "★" : "☆")
            </button>
        }
    </span>
    <span class="text-muted ms-2">
        @_average.ToString("0.0") avg · @_totalRatings rating@(_totalRatings == 1 ? "" : "s")
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private double _average;
    private int _totalRatings;
    private int _hovering;
    private bool _hasRated;
    private int _userRating;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        if (_hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        _userRating = stars;
        _hasRated = true;
        _hovering = 0;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            _average = recipe.AverageRating;
            _totalRatings = recipe.TotalRatings;
        }
    }
}

.star-rating .btn-star {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    padding: 0 2px;
    color: #ccc;
    transition: color 0.15s;
}

.star-rating .btn-star.active {
    color: #ffc107;
}

.star-rating .btn-star:hover:not(:disabled) {
    color: #ffab00;
    transform: scale(1.2);
}

.star-rating .btn-star:disabled {
    cursor: default;
    opacity: 0.8;
}

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
