@rendermode InteractiveServer
@using RecipeShare.Services

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added.</p>
        <a href="recipe/@_submittedId" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="needs-validation">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_title" class="form-control" placeholder="e.g., Grandma's Apple Pie" required />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_category" class="form-select" required>
                <option value="">— Select a category —</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Short Description</label>
            <InputTextArea id="description" @bind-Value="_description" class="form-control" rows="2"
                placeholder="A brief description of your recipe" required />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients</label>
            @for (int i = 0; i < _ingredients.Count; i++)
            {
                var index = i;
                <div class="input-group mb-2">
                    <input type="text" class="form-control" value="@_ingredients[index]"
                        placeholder="e.g., 2 cups flour"
                        @onchange="(e) => _ingredients[index] = e.Value?.ToString() ?? string.Empty" />
                    @if (_ingredients.Count > 1)
                    {
                        <button type="button" class="btn btn-outline-danger" @onclick="() => RemoveIngredient(index)">✕</button>
                    }
                </div>
            }
            <button type="button" class="btn btn-outline-secondary btn-sm" @onclick="AddIngredient">+ Add Ingredient</button>
        </div>

        <div class="mb-3">
            <label class="form-label">Steps</label>
            @for (int i = 0; i < _steps.Count; i++)
            {
                var index = i;
                <div class="input-group mb-2">
                    <span class="input-group-text">@(index + 1)</span>
                    <input type="text" class="form-control" value="@_steps[index]"
                        placeholder="Describe this step..."
                        @onchange="(e) => _steps[index] = e.Value?.ToString() ?? string.Empty" />
                    @if (_steps.Count > 1)
                    {
                        <button type="button" class="btn btn-outline-danger" @onclick="() => RemoveStep(index)">✕</button>
                    }
                </div>
            }
            <button type="button" class="btn btn-outline-secondary btn-sm" @onclick="AddStep">+ Add Step</button>
        </div>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="alert alert-danger">@_error</div>
        }

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _description = string.Empty;
    private List<string> _ingredients = [string.Empty];
    private List<string> _steps = [string.Empty];
    private string _error = string.Empty;
    private bool _submitted;
    private int _submittedId;
    private IReadOnlyList<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void AddIngredient() => _ingredients.Add(string.Empty);
    private void RemoveIngredient(int index) => _ingredients.RemoveAt(index);
    private void AddStep() => _steps.Add(string.Empty);
    private void RemoveStep(int index) => _steps.RemoveAt(index);

    private void HandleSubmit()
    {
        var ingredients = _ingredients.Where(i => !string.IsNullOrWhiteSpace(i)).ToList();
        var steps = _steps.Where(s => !string.IsNullOrWhiteSpace(s)).ToList();

        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category)
            || ingredients.Count == 0 || steps.Count == 0)
        {
            _error = "Please fill in all fields with at least one ingredient and one step.";
            return;
        }

        var recipe = RecipeService.AddRecipe(_title, _category, _description, ingredients, steps);
        _submittedId = recipe.Id;
        _submitted = true;
        _error = string.Empty;
    }

    private void ResetForm()
    {
        _title = string.Empty;
        _category = string.Empty;
        _description = string.Empty;
        _ingredients = [string.Empty];
        _steps = [string.Empty];
        _submitted = false;
        _error = string.Empty;
    }
}
"}

{"path": "/tmp/sv-f6f84484747c43b2a988f2741fc2f2ae/RecipeShare/Components/StarRating.razor", "file_text": "@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating my-3">
    @if (_hasRated)
    {
        <div class="alert alert-info py-2 px-3 d-inline-block">
            You rated this recipe @_userRating star@(_userRating == 1 ? "" : "s"). Thanks!
        </div>
        <br />
    }

    <span class="stars" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                class="btn-star @(star <= (_hovering > 0 ? _hovering : (int)Math.Round(_average)) ? "active" : "")"
                @onclick="() => Rate(star)"
                @onmouseover="() => _hovering = star"
                @onmouseout="() => _hovering = 0"
                disabled="@_hasRated"
                aria-label="Rate @star star@(star == 1 ? "" : "s")">
                @(star <= (_hovering > 0 ? _hovering : (int)Math.Round(_average)) ? "★" : "☆")
            </button>
        }
    </span>
    <span class="text-muted ms-2">
        @_average.ToString("0.0") avg · @_totalRatings rating@(_totalRatings == 1 ? "" : "s")
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private double _average;
    private int _totalRatings;
    private int _hovering;
    private bool _hasRated;
    private int _userRating;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        if (_hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        _userRating = stars;
        _hasRated = true;
        _hovering = 0;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            _average = recipe.AverageRating;
            _totalRatings = recipe.TotalRatings;
        }
    }
}
"}

{"path": "/tmp/sv-f6f84484747c43b2a988f2741fc2f2ae/RecipeShare/Components/StarRating.razor.css", "file_text": ".star-rating .btn-star {
    background: none;
