toolArgs.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone.",
                    "Stretch dough into a 12-inch round.",
                    "Spread crushed tomatoes over the dough.",
                    "Tear mozzarella and distribute evenly.",
                    "Bake for 10-12 minutes until crust is golden.",
                    "Top with fresh basil and a drizzle of olive oil."
                ],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted water until al dente.",
                    "Fry pancetta until crispy.",
                    "Whisk eggs with grated pecorino and pepper.",
                    "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.",
                    "Serve immediately with extra cheese and pepper."
                ],
                TotalRatings = 8, RatingSum = 36
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until charred.",
                    "Sauté onion, garlic, and ginger. Add tomato sauce and spices.",
                    "Simmer sauce for 15 minutes, then add cream.",
                    "Add chicken pieces and cook for 5 more minutes.",
                    "Serve with basmati rice or naan."
                ],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "Sweet, sour, and savory Thai noodles loaded with vegetables.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Eggs"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes.",
                    "Make sauce: mix tamarind paste, fish sauce, sugar, and lime juice.",
                    "Stir-fry tofu until golden, set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss with bean sprouts and tofu.",
                    "Serve with crushed peanuts and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef and drain excess fat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm tortillas in a dry skillet.",
                    "Fill tortillas with beef and desired toppings.",
                    "Serve with salsa and sour cream on the side."
                ],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit avocados, scoop into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, jalapeño, tomato, and cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 7, Title = "Japanese Miso Soup", Category = "Asian",
                Description = "Light and comforting soup with tofu and seaweed.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Green onion"],
                Steps = [
                    "Bring dashi stock to a gentle simmer.",
                    "Dissolve miso paste in a small amount of broth, then add to pot.",
                    "Add cubed tofu and rehydrated wakame.",
                    "Heat through without boiling (boiling destroys miso flavor).",
                    "Serve garnished with sliced green onion."
                ],
                TotalRatings = 5, RatingSum = 22
            },
            new Recipe
            {
                Id = 8, Title = "Palak Paneer", Category = "Indian",
                Description = "Creamy spinach curry with cubes of fresh paneer cheese.",
                Ingredients = ["Spinach", "Paneer", "Onion", "Garlic", "Ginger", "Green chili", "Cream", "Cumin seeds"],
                Steps = [
                    "Blanch spinach and blend into a smooth puree.",
                    "Fry paneer cubes until golden, set aside.",
                    "Sauté cumin seeds, onion, garlic, ginger, and green chili.",
                    "Add spinach puree and cook for 5 minutes.",
                    "Add paneer and cream, simmer for 3 minutes.",
                    "Serve with roti or rice."
                ],
                TotalRatings = 7, RatingSum = 31
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

