.star-rating .btn-star {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    padding: 0 2px;
    color: #ccc;
    transition: color 0.15s;
}

.star-rating .btn-star.active {
    color: #ffc107;
}

.star-rating .btn-star:hover:not(:disabled) {
    color: #ffab00;
    transform: scale(1.2);
}

.star-rating .btn-star:disabled {
    cursor: default;
    opacity: 0.8;
}

