﻿@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍽️ RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in _categories)
    {
        <div class="col-md-6 col-lg-3 mb-4">
            <a href="category/@category" class="text-decoration-none">
                <div class="card text-center h-100 category-card">
                    <div class="card-body">
                        <div class="display-6 mb-2">@GetCategoryEmoji(category)</div>
                        <h5 class="card-title">@category</h5>
                        <p class="text-muted">@RecipeService.GetByCategory(category).Count recipe(s)</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-4">
    <a href="/submit" class="btn btn-primary btn-lg">Submit Your Recipe</a>
</div>

@code {
    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        _ => "🍴"
    };
}

